// Host-only microbenchmark of the actual WPD4-backed 7x8 Cyrillic hint DFS.
// Corpus is a deterministic SYNTHETIC six-symbol dictionary generated by
// tools/check/bench_cyr_hint.py, not Russian/Ukrainian linguistic content.
// Output fingerprints must agree between baseline and optimized engines.
// Timing is host wall time, NEVER Nintendo DS FPS or real hardware cycles.
#define _POSIX_C_SOURCE 200809L
#include "script_board.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static double now(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (double)ts.tv_sec + ts.tv_nsec * 0.000000001;
}
static uint8_t *readFile(const char *name, size_t *bytes)
{
    FILE *f = fopen(name, "rb");
    if (!f) return NULL;
    if (fseek(f, 0, SEEK_END)) { fclose(f); return NULL; }
    long length = ftell(f);
    if (length < 1 || fseek(f, 0, SEEK_SET)) { fclose(f); return NULL; }
    uint8_t *data = malloc((size_t)length);
    if (!data) { fclose(f); return NULL; }
    if (fread(data, 1, (size_t)length, f) != (size_t)length) {
        free(data); fclose(f); return NULL;
    }
    fclose(f);
    *bytes = (size_t)length;
    return data;
}
static uint32_t step(uint32_t hash, uint8_t next)
{
    return (hash ^ next) * 16777619u;
}
int main(int argc, char **argv)
{
    if (argc != 6) {
        fprintf(stderr, "usage: %s dict.bin tiles.bin ru|uk boards repeats\n", argv[0]);
        return 2;
    }
    size_t db = 0, tb = 0;
    uint8_t *dictData = readFile(argv[1], &db);
    uint8_t *tileData = readFile(argv[2], &tb);
    if (!dictData || !tileData) { free(dictData); free(tileData); return 2; }
    int boards = atoi(argv[4]), repeats = atoi(argv[5]);
    if (boards < 1 || boards > 2000 || repeats < 1 || repeats > 100) {
        free(dictData); free(tileData); return 2;
    }
    V4Dict dict;
    V4Tiles tiles;
    if (!v4DictOpen(&dict, dictData, db) ||
        !v4TilesOpen(&tiles, tileData, tb, &dict)) {
        free(dictData); free(tileData); return 2;
    }
    unsigned found = 0, total = 0;
    uint32_t fingerprint = 2166136261u;
    double beginning = now();
    for (int pass = 0; pass < repeats; pass++) {
        for (int seed = 0; seed < boards; seed++) {
            ScriptBoard board, snapshot;
            uint32_t num = 0x4891bda5u + (uint32_t)seed * 7919u +
                           (uint32_t)pass * 100003u;
            if (!scriptBoardStart(&board, &tiles, num)) return 3;
            // Compare the prefix-search algorithms on IDENTICAL board
            // positions. Production shelf dealing may change independently
            // (e.g. its vowel-floor fair shuffle). Regenerate a canonical
            // WPL2 bag using the same seed and replace only the 56 visible
            // tile IDs before timing the hint. Both old/new compilers use
            // this exact harness and therefore start from equal evidence.
            uint8_t canonical[WPL2_BAG_SIZE];
            if (!v4TilesFill(&tiles, canonical, num)) return 3;
            for (int col = 0; col < SCRIPT_COLS; col++)
                for (int row = 0; row < SCRIPT_ROWS; row++)
                    board.tile[col][row] = canonical[col * SCRIPT_ROWS + row];
            snapshot = board;
            uint8_t c[SCRIPT_HINT_MAX] = {0}, r[SCRIPT_HINT_MAX] = {0};
            int n = scriptBoardHint(&board, &dict, &tiles, c, r);
            if (memcmp(&board, &snapshot, sizeof board) != 0) {
                fprintf(stderr, "hint mutated the board\n");
                return 4;
            }
            if (n < 0 || n > SCRIPT_HINT_MAX) return 4;
            fingerprint = step(fingerprint, (uint8_t)n);
            if (n > 0) {
                ScriptBoard selected = board;
                found++;
                selected.chainLen = (uint8_t)n;
                for (int i = 0; i < n; i++) {
                    if (c[i] >= SCRIPT_COLS || r[i] >= SCRIPT_ROWS) return 4;
                    selected.chainC[i] = c[i];
                    selected.chainR[i] = r[i];
                    fingerprint = step(step(fingerprint, c[i]), r[i]);
                }
                if (scriptBoardPreview(&selected, &dict, &tiles, NULL) <= 0) {
                    fprintf(stderr, "hint did not return a real accepted word\n");
                    return 4;
                }
            }
            total++;
        }
    }
    double elapsed = 1000.0 * (now() - beginning);
    printf("language=%s total=%u found=%u fingerprint=%08x elapsed_ms=%.3f\n",
           argv[3], total, found, fingerprint, elapsed);
    free(dictData); free(tileData);
    return 0;
}
